// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether * 1000000);
        vm.deal(address(this), amount);
        // deposit through the payable fallback
        (bool s, ) = address(c).call{value: amount}("");
        require(s, "deposit failed");

        // owner (this contract, since it deployed c) drains the contract
        uint256 ownerBefore = address(this).balance;
        c.withdrawAll();

        // RULE: withdrawAll always moves the ENTIRE balance to the owner;
        // the mutant keeps 1 wei in the contract, so the owner receives amount-1.
        assertTrue(address(this).balance - ownerBefore == amount && address(c).balance == 0);
    }
}
